const nextConfig: NextConfig = {
  async headers() {
    return [
      {
        // Vue 预览 iframe 使用 sandbox="allow-scripts"（无 allow-same-origin），
        // 本地模块导入需跨源，放开 CORS 使 /vue.esm-browser.js 可被模块脚本加载。
        source: '/vue.esm-browser.js',
        headers: [{ key: 'Access-Control-Allow-Origin', value: '*' }],
      },
    ];
  },
  // 代理到 lostsystem 知识库 RAG 后端（认证 / 问答 / 检索），绕开浏览器跨域。
  // /kb-auth/*    → /auth/*      （登录、注册）
  // /kb-api/*     → /api/kb/*    （SSE 问答、混合检索、历史、清空历史）
  // /kb-admin/*   → /admin/kb/*  （管理：文档导入、统计，需 ADMIN）
  // 后端地址经环境变量 KB_BACKEND_ORIGIN 配置（部署时必填），本地开发回落 8081。
  async rewrites() {
    const backend = process.env.KB_BACKEND_ORIGIN ?? "http://localhost:8081";
    return [
      { source: "/kb-auth/:path*", destination: `${backend}/auth/:path*` },
      { source: "/kb-api/:path*", destination: `${backend}/api/kb/:path*` },
      { source: "/kb-admin/:path*", destination: `${backend}/admin/kb/:path*` },
    ];
  },


  async redirects() {
    const legacy = Object.entries(PYTHON_LEGACY_MAP).map(([slug, subPath]) => ({
      source: `/docs/${slug}/:path*`,
      destination: `/docs/python/${subPath}/:path*`,
      permanent: true,
    }));
    const dirRename = Object.entries(PYTHON_DIR_RENAME).map(([from, to]) => ({
      source: `/docs/python/${from}/:path*`,
      destination: `/docs/python/${to}/:path*`,
      permanent: true,
    }));
    // 产品收敛：租户概念退出 UI，「我的租户」页由「我的知识库」承接
    const productRedirects = [
      { source: "/admin/my-tenant", destination: "/my/kb", permanent: false },
    ];
    return [ ...productRedirects, ...REFACTOR_REDIRECT, ...legacy, ...dirRename, ...DATA_SCIENCE_REDIRECT, ...ARCH_MERGE_REDIRECT, ...ARCH_INTEGRATE_REDIRECT, ...ZHT_MOVE_REDIRECT, ...XU_SPLIT_REDIRECT, ...RENUMBER_REDIRECTS, ...SPLIT_DOC_REDIRECTS, ...FILE_RENUMBER_REDIRECTS];
  },
};

